//! The firmware files GRID knows without RomM: `firmware-known.json` at the
//! repo root (romm-storefront-plan 0.9). Generated by
//! `scripts/data/gen_firmware_known_json.py` from libretro's System.dat
//! (pinned commit, CC BY-SA 4.0) and keyed `<slug>:<name>` the way RomM
//! 5.4.1's `known_bios_files.json` keys it. An entry with an empty md5 is a
//! per-console file (keys, a system update): it installs as "Installed ·
//! not verified" (user decision 13).
//!
//! The `e2e` build reads `GRID_LAUNCHER_E2E_FIRMWARE_KNOWN` (a path to a
//! table of the same shape) instead, so the suite's fixtures are fake files
//! with fake hashes; a release build never reads it.

use std::sync::OnceLock;

use serde::Deserialize;

const FIRMWARE_KNOWN_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../firmware-known.json"
));

/// How an emulator finds the file.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum MatchKind {
    /// By its file name.
    Name,
    /// By its content (DuckStation, PCSX2, Ymir): any BIOS dump of the
    /// system serves, whatever it is called.
    Content,
}

/// One known firmware file.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct KnownFile {
    pub slug: String,
    pub name: String,
    /// The folder libretro's System.dat puts it in under `system/` (`dc/`).
    #[serde(default)]
    pub path_hint: String,
    /// `0`: not fixed.
    #[serde(default)]
    pub size: u64,
    /// Lower-case hex; `""`: no fixed checksum (name-only).
    #[serde(default)]
    pub md5: String,
    #[serde(default)]
    pub sha1: String,
    #[serde(default)]
    pub crc: String,
    /// The system needs it (or, with a `group`, one file of its group).
    #[serde(default)]
    pub required: bool,
    /// Files that stand in for one another (one region's BIOS of several).
    #[serde(default)]
    pub group: String,
    #[serde(rename = "match", default = "name_match")]
    pub matching: MatchKind,
    /// Emulator profiles it applies to; empty: every emulator of the slug.
    #[serde(default)]
    pub profiles: Vec<String>,
    #[serde(default)]
    pub source: String,
}

fn name_match() -> MatchKind {
    MatchKind::Name
}

impl KnownFile {
    /// Whether GRID can check the file: it has a fixed MD5.
    pub fn has_hash(&self) -> bool {
        !self.md5.trim().is_empty()
    }

    /// Whether the entry applies to an emulator with `profile` (its
    /// autoprofile name), or to any emulator when `None`.
    pub fn applies_to(&self, profile: Option<&str>) -> bool {
        match profile {
            _ if self.profiles.is_empty() => true,
            Some(name) => self
                .profiles
                .iter()
                .any(|p| p.eq_ignore_ascii_case(name.trim())),
            None => true,
        }
    }
}

#[derive(Deserialize)]
struct KnownTable {
    files: Vec<KnownFile>,
}

/// Parses a `firmware-known.json` body.
pub fn parse_known(json: &str) -> Result<Vec<KnownFile>, String> {
    let table: KnownTable = serde_json::from_str(json).map_err(|e| e.to_string())?;
    Ok(table
        .files
        .into_iter()
        .map(|mut f| {
            f.slug = f.slug.trim().to_lowercase();
            f.md5 = f.md5.trim().to_lowercase();
            f
        })
        .collect())
}

/// The e2e table override's variable.
#[cfg(feature = "e2e")]
pub const E2E_FIRMWARE_KNOWN_VAR: &str = "GRID_LAUNCHER_E2E_FIRMWARE_KNOWN";

fn load() -> Vec<KnownFile> {
    #[cfg(feature = "e2e")]
    if let Some(path) = std::env::var_os(E2E_FIRMWARE_KNOWN_VAR) {
        match std::fs::read_to_string(&path)
            .map_err(|e| e.to_string())
            .and_then(|t| parse_known(&t))
        {
            Ok(files) => return files,
            Err(e) => tracing::warn!("e2e firmware table not read: {e}"),
        }
    }
    parse_known(FIRMWARE_KNOWN_JSON)
        .expect("firmware-known.json is embedded at build time and must be valid")
}

/// Every known file, parsed once.
pub fn known_files() -> &'static [KnownFile] {
    static FILES: OnceLock<Vec<KnownFile>> = OnceLock::new();
    FILES.get_or_init(load)
}

/// The known files for `slug` (slug aliases folded) that apply to an
/// emulator with `profile`.
pub fn files_for<'a>(
    files: &'a [KnownFile],
    slug: &str,
    profile: Option<&str>,
) -> Vec<&'a KnownFile> {
    let slug = crate::systems::canonical_slug(slug);
    files
        .iter()
        .filter(|f| f.slug == slug && f.applies_to(profile))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_bundled_table_parses_with_its_attribution() {
        assert!(FIRMWARE_KNOWN_JSON.contains("CC BY-SA 4.0"));
        assert!(FIRMWARE_KNOWN_JSON.contains("ShareAlike"));
        assert!(FIRMWARE_KNOWN_JSON.contains("2a8de0276fd7d3095f2501c3de3799a14c37e910"));
        let files = parse_known(FIRMWARE_KNOWN_JSON).unwrap();
        assert!(files.len() > 400, "{}", files.len());
        for f in &files {
            assert!(!f.name.is_empty() && !f.slug.is_empty());
            assert!(
                f.md5.is_empty() || f.md5.len() == 32,
                "{}:{}",
                f.slug,
                f.name
            );
        }
    }

    #[test]
    fn per_console_files_are_name_only() {
        let files = parse_known(FIRMWARE_KNOWN_JSON).unwrap();
        for (slug, name) in [
            ("switch", "prod.keys"),
            ("switch", "title.keys"),
            ("wiiu", "keys.txt"),
            ("3ds", "aes_keys.txt"),
            ("ps3", "PS3UPDAT.PUP"),
            ("psvita", "PSVUPDAT.PUP"),
            ("nds", "firmware.bin"),
            ("xbox", "eeprom.bin"),
        ] {
            let found: Vec<&KnownFile> = files
                .iter()
                .filter(|f| f.slug == slug && f.name == name)
                .collect();
            assert!(!found.is_empty(), "{slug}:{name} missing");
            assert!(
                found.iter().all(|f| !f.has_hash()),
                "{slug}:{name} must not carry a hash"
            );
        }
    }

    #[test]
    fn content_matched_systems_are_marked() {
        let files = parse_known(FIRMWARE_KNOWN_JSON).unwrap();
        for slug in ["psx", "ps2", "saturn"] {
            assert!(
                files
                    .iter()
                    .any(|f| f.slug == slug && f.matching == MatchKind::Content && f.required),
                "{slug}"
            );
        }
        assert!(files
            .iter()
            .all(|f| f.matching == MatchKind::Name || f.has_hash()));
    }

    #[test]
    fn files_for_filters_by_slug_and_profile() {
        let files = parse_known(
            r#"{"files":[
              {"slug":"psx","name":"a.bin","size":1,"md5":"","profiles":[]},
              {"slug":"psx","name":"b.bin","size":1,"md5":"","profiles":["DuckStation (Playstation 1)"]},
              {"slug":"snes","name":"c.bin","size":1,"md5":""}
            ]}"#,
        )
        .unwrap();
        let names = |p: Option<&str>| -> Vec<String> {
            files_for(&files, "PSX", p)
                .iter()
                .map(|f| f.name.clone())
                .collect()
        };
        assert_eq!(
            names(Some("DuckStation (Playstation 1)")),
            vec!["a.bin", "b.bin"]
        );
        assert_eq!(names(Some("RetroArch (Multi-System)")), vec!["a.bin"]);
        assert_eq!(names(None), vec!["a.bin", "b.bin"]);
    }
}
